using System;
using System.Net;
using System.Threading;
using System.Threading.Tasks;
using UnityEngine;
using System.IO;
using ViverseSDK.Login;

public class HttpServer : MonoBehaviour
{
    public const int HTTP_PORT = 40078;
    private HttpListener m_HttpListener;
    private string logFilePath;
    private string accessToken;

    public static event System.Action<string> OnAuthCallbackReceived;


    private void Awake()
    {
        logFilePath = Path.Combine(Application.persistentDataPath, "log.txt");
        Debug.Log($"[HttpServer] Application.persistentDataPath: {Application.persistentDataPath}");
    }

    public void OnAuthCallback(string resultJson)
    {
        Debug.Log($"[HttpServer] Auth Callback: {resultJson}");

        try
        {
            var json = JsonUtility.FromJson<AuthResultWrapper>(resultJson);
            if (json.data != null && !string.IsNullOrEmpty(json.data.access_token))
            {
                accessToken = json.data.access_token;
                string accountId = json.data.account_id;

                // Save to PlayerPrefs for persistence
                PlayerPrefs.SetString("access_token", accessToken);
                PlayerPrefs.SetString("account_id", accountId);
                PlayerPrefs.Save();
                Debug.Log($"[HttpServer] Token and account_id saved successfully");

                // Notify subscribers via event system instead of direct coupling
                OnAuthCallbackReceived?.Invoke("Login successful!");
            }
            else
            {
                Debug.LogWarning("[HttpServer] Login failed or access_token not received");
                OnAuthCallbackReceived?.Invoke("Login failed or access_token not received.");
            }
        }
        catch (Exception ex)
        {
            Debug.LogError($"[HttpServer] JSON parse error: {ex.Message}");
            OnAuthCallbackReceived?.Invoke($"Login failed: {ex.Message}");
        }
    }

    [Serializable]
    public class AuthResultWrapper
    {
        public AuthResult data;
    }

    // Also need to update the AuthResult class:
    [Serializable]
    public class AuthResult
    {
        public string access_token;
        public string account_id;
    }

    public void StartServer()
    {
        if (m_HttpListener != null && m_HttpListener.IsListening)
        {
            Debug.Log("HttpServer is already running.");
            return;
        }

        try
        {
            Task.Run(() => InitListener());
        }
        catch (Exception ex)
        {
            Debug.LogError($"Failed to start HttpServer: {ex.Message}");
            WriteLog($"Failed to start HttpServer: {ex.Message}");
        }
    }

    private void InitListener()
    {
        try
        {
            m_HttpListener = new HttpListener();
            m_HttpListener.Prefixes.Add($"http://localhost:{HTTP_PORT}/");
            m_HttpListener.Start();
            Debug.Log($"HttpServer started at http://localhost:{HTTP_PORT}/");
            WriteLog($"HttpServer started at http://localhost:{HTTP_PORT}/");

            ThreadPool.QueueUserWorkItem((o) =>
            {
                while (m_HttpListener != null && m_HttpListener.IsListening)
                {
                    try
                    {
                        HttpListenerContext ctx = m_HttpListener.GetContext();
                        HandleRequest(ctx);
                    }
                    catch (HttpListenerException)
                    {
                        // This exception may be thrown when the server is closed, which is normal
                    }
                    catch (Exception ex)
                    {
                        Debug.LogError($"Error while handling request: {ex.Message}");
                        WriteLog($"Error while handling request: {ex.Message}");
                    }
                }
            });
        }
        catch (Exception ex)
        {
            Debug.LogError($"Failed to start HttpListener: {ex}");
            WriteLog($"Failed to start HttpListener: {ex}");
            m_HttpListener = null;
        }
    }

    private void HandleRequest(HttpListenerContext context)
    {
        string path = context.Request.Url.AbsolutePath;
        string method = context.Request.HttpMethod;

        WriteLog($"Request: {method} {path}");

        if (path == "/api/viverse/auth/callback" && method == "POST")
        {
            using (var reader = new StreamReader(context.Request.InputStream, context.Request.ContentEncoding))
            {
                string body = reader.ReadToEnd();
                WriteLog($"Received VIVERSE POST data: {body}");

                bool hasAccessToken = body.Contains("access_token");

                LoginManager.RunOnMainThread(() =>
                {
                    OnAuthCallback(body);
                });

                string response = "{\"status\":\"ok\"}";
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response);
                context.Response.ContentLength64 = buffer.Length;
                context.Response.ContentType = "application/json";
                context.Response.OutputStream.Write(buffer, 0, buffer.Length);
                context.Response.OutputStream.Close();
            }
        }
        else
        {
            // Generate HTML directly in code, do not read any files
            string responseString = @"<!DOCTYPE html>
<html lang=""en"">

<head>
  <meta charset=""UTF-8"">
  <meta name=""viewport"" content=""width=device-width, initial-scale=1.0"">
  <title>VIVERSE Login</title>
  <script defer src=""https://www.viverse.com/static-assets/viverse-sdk/1.3.0/index.umd.cjs""></script>
  <style>
    body {
      font-family: Arial, sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      margin: 0;
      background-color: #f0f0f0;
    }

    #main-content {
      display: none;
    }

    .container {
      text-align: center;
      background: white;
      padding: 20px;
      border-radius: 8px;
      box-shadow: 0 4px 8px rgba(91, 90, 90, 0.1);
    }

    p {
      font-size: 32px;
      color: #333;
    }

    .branding img {
      width: 320px;
    }
  </style>
</head>

<body>
  <!-- <h1>VIVERSE</h1>
  <br />
  <div class=""logs"">
    <h2>Login Status</h2>
    <textarea id=""redirect-status"" readonly cols=""100"" rows=""20""></textarea>
  </div> -->

  <div id=""main-content"" class=""container"">
    <div class=""branding"">
      <img
        src=""data:image/png;base64,""
        alt=""Viverse Logo"" />
    </div>
    <p>Return to your content to continue creating.</p>
  </div>

  <script>
    const viverseClientID = '42ab6113-acc9-419e-93ca-e0734baf9d3d';
    const viverseDomain = 'account.htcvive.com';

    function initializeViverseClient() {
      return new Promise((resolve) => {
        if (window.viverse && window.viverse.Client) {
          resolve(new window.viverse.Client({
            clientId: viverseClientID,
            domain: viverseDomain,
            authorizationParams: {
              authorities: ""htc.com google.com steam.com""
            },
          }));
        } else {
          setTimeout(() => resolve(initializeViverseClient()), 300);
        }
      });
    }

    async function login() {
      const viverseClient = await initializeViverseClient();
      try {
        await viverseClient.loginWithRedirect();
      } catch (error) {
        console.error('Login failed:', error);
      }
    }

    window.addEventListener('load', async () => {
      if (
        window.location.search.includes('code=') &&
        window.location.search.includes('state=')
      ) {
        const viverseClient = await initializeViverseClient();
        const result = await viverseClient.handleRedirectCallback();
        // const redirectStatus = document.getElementById('redirect-status');
        // redirectStatus.value = JSON.stringify(result, null, 2);

        // const avatarClient = new window.viverse.Avatar({
        //   baseURL: 'https://sdk-api.viverse.com/',
        //   token: await viverseClient.getToken(),
        // });

        // avatarClient.getProfile().then(profile => {
        //   console.log('User profile:', profile);
        // });

        // send request to backend
        const response = await fetch('/api/viverse/auth/callback', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            data: result,
          }),
        });

        // show main content
        document.getElementById('main-content').style.display = 'block';
      } else {
        login();
      }
    });
  </script>
</body>

</html>";
            WriteLog($"Response: HTML page for {path}");
            byte[] buffer = System.Text.Encoding.UTF8.GetBytes(responseString);
            context.Response.ContentLength64 = buffer.Length;
            context.Response.ContentType = "text/html";
            context.Response.OutputStream.Write(buffer, 0, buffer.Length);
            context.Response.OutputStream.Close();
        }
    }

    private void WriteLog(string message)
    {
        try
        {
            File.AppendAllText(logFilePath, $"{DateTime.Now:yyyy-MM-dd HH:mm:ss} {message}\n");
        }
        catch (Exception ex)
        {
            Debug.LogError($"Failed to write log: {ex.Message}");
        }
    }

    private void OnDestroy()
    {
        if (m_HttpListener != null)
        {
            m_HttpListener.Close();
            m_HttpListener = null;
        }
    }
}

